B.agy=s([B.Q6,B.b37,B.b39],t.u)
B.bBL=new A.bq(1,"vrznut\xedm","sfx_story_locker_creak",null,1)
B.bAY=new A.bq(1,"vypadne","sfx_story_scroll_drop",null,1)
