B.b5e=new A.e(0,0,170.20355132091814,311.82330012992634)
B.b5Z=new A.e(120,0,311.85794716327416,170.20355132091814)
B.b2H=new A.e(129.9,129.9,311.79692507579034,311.79692507579034)
B.la=s([B.b5e,B.b5Z,B.b2H],t.u)
B.ay_=new A.aQ("Za jednou vesnic\xed roste velk\xfd les, kter\xfd nezn\xe1 \u017e\xe1dn\xfd nudn\xfd dosp\u011bl\xe1k. V n\u011bm stoj\xed star\xe1 vrba s tajnou klubovnou uvnit\u0159 kmene. Dnes se k n\xed poprv\xe9 bl\xed\u017e\xed\u0161 i ty. A to zrovna v den, kdy maj\xed str\xe1\u017eci stolet\xe9 narozeniny.")
B.cH=new A.kr("marek","assets/images/stories/forest_rangers/portrait_marek.webp")
B.aep=s(["\u201eSt\u016fj! Dovnit\u0159 sm\xed jen ten, kdo zn\xe1 tajn\xfd pozdrav.\u201c"],t.s)
B.bl_=new A.a6(B.cH,B.aep,!1)
B.bW=new A.kr("karel","assets/images/stories/forest_rangers/portrait_karel.webp")
B.aiZ=s(["\u201eChce\u0161 se k n\xe1m p\u0159idat? M\xe1\u0161 dobr\xfd post\u0159eh?\u201c"],t.s)
B.bnB=new A.a6(B.bW,B.aiZ,!1)
B.aoJ=s([B.ay_,B.bl_,B.bnB],t.a)
B.bpa=new A.cq("story_00_intro",B.aoJ)
B.axi=new A.aQ("Dve\u0159e se otev\u0159ou do tmy a ty vstoup\xed\u0161 dovnit\u0159. Klubovna von\xed d\u0159evem a star\xfdm pap\xedrem. Uprost\u0159ed stoj\xed st\u016fl a na n\u011bm le\u017e\xed podivn\xfd den\xedk.")
B.afc=s(["\u201eDve\u0159e se otev\u0159ely, tak\u017ee pozdrav u\u017e zn\xe1\u0161. J\xe1 se jmenuji Marek, tamto byl Karel a tohle je Tereza. Poj\u010f d\xe1l.\u201c"],t.s)
B.bl9=new A.a6(B.cH,B.afc,!1)
B.ay6=new A.aQ("Za dve\u0159mi se ozve hlasit\xe9 \u017euchnut\xed.")
B.afm=s(["\u201eJsem v po\u0159\xe1dku! Spadl jsem schv\xe1ln\u011b, abych prolomil ledy.\u201c"],t.s)
B.bl5=new A.a6(B.bW,B.afm,!1)
B.cS=new A.kr("tereza","assets/images/stories/forest_rangers/portrait_tereza.webp")
B.apY=s(["\u201eMarku! N\xe1\u0161 den\xedk nejde otev\u0159\xedt.\u201c","\u201eV\u010dera ve\u010der ho omotala divok\xe1 li\xe1na.\u201c","\u201eZkou\u0161eli jsme ji odmotat, ale li\xe1na dr\u017e\xed jako p\u0159ilepen\xe1.\u201c"],t.s)
B.bnm=new A.a6(B.cS,B.apY,!1)
B.afI=s(["\u201eBez den\xedku nem\u016f\u017eeme d\u011blat pr\u016fzkum lesa.\u201c"],t.s)
B.bmE=new A.a6(B.cH,B.afI,!1)
B.aoW=s([B.axi,B.bl9,B.ay6,B.bl5,B.bnm,B.bmE],t.a)
B.boL=new A.cq("story_01a_clubhouse_arrival",B.aoW)
B.ahd=s(["\u201eA dneska to pot\u0159ebujeme v\xedc ne\u017e kdy jindy! Klub m\xe1 st\xe9 narozeniny.\u201c"],t.s)
B.blO=new A.a6(B.cH,B.ahd,!1)
B.ajm=s(["\u201ePodle legendy se pr\xe1v\u011b dnes d\xe1 naj\xedt to, co po sob\u011b zakladatel\xe9 nechali. Jen\u017ee jen do z\xe1padu slunce.\u201c"],t.s)
B.bmL=new A.a6(B.cS,B.ajm,!1)
B.ad2=s(["\u201ePoklad! T\u0159eba jedl\xfd poklad. Dort! Ur\u010dit\u011b to bude dort.\u201c"],t.s)
B.bn6=new A.a6(B.bW,B.ad2,!1)
B.afh=s(["\u201eNikdo ne\u0159ekl poklad.\u201c"],t.s)
B.bn2=new A.a6(B.cS,B.afh,!1)
B.aes=s(["\u201eNikdo ne\u0159ekl, \u017ee nen\xed.\u201c"],t.s)
B.bm5=new A.a6(B.bW,B.aes,!1)
B.abM=s(["\u201eCokoliv to je, najdeme to. Dal\u0161\xed \u0161ance p\u0159ijde a\u017e za sto let.\u201c"],t.s)
B.bkK=new A.a6(B.cH,B.abM,!1)
B.amh=s(["\u201eTo bych ten dort nestihl ochutnat.\u201c"],t.s)
B.bnH=new A.a6(B.bW,B.amh,!1)
B.arK=s([B.blO,B.bmL,B.bn6,B.bn2,B.bm5,B.bkK,B.bnH],t.a)
B.boE=new A.cq("story_01b_legend_and_time",B.arK)
B.ayK=new A.aQ("Li\xe1na povol\xed, den\xedk se otev\u0159e a vypadne z n\u011bj hrom\xe1dka pap\xedrov\xfdch \xfatr\u017ek\u016f.")
B.ahm=s(["\u201eTo je star\xe1 mapa lesa!\u201c"],t.s)
B.blV=new A.a6(B.bW,B.ahm,!1)
B.agq=s(["\u201eAle ne, n\u011bkdo ji roztrhal. Karle?\u201c"],t.s)
B.bnS=new A.a6(B.cS,B.agq,!1)
B.aqX=s(["\u201eJ\xe1 to nebyl. \u2026 Asi.\u201c"],t.s)
B.bn1=new A.a6(B.bW,B.aqX,!1)
B.alG=s(["\u201ePap\xedr je star\u0161\xed ne\u017e na\u0161e babi\u010dky. Tenhle se roztrhne i s\xe1m.\u201c"],t.s)
B.bkE=new A.a6(B.cS,B.alG,!1)
B.ae7=s(["\u201eDob\u0159e. Co te\u010f s t\xedm?\u201c"],t.s)
B.bkH=new A.a6(B.cH,B.ae7,!1)
B.ajZ=s([B.ayK,B.blV,B.bnS,B.bn1,B.bkE,B.bkH],t.a)
B.boD=new A.cq("story_02_torn_map",B.ajZ)
B.ad3=s(["\u201eKoukejte! To je cesta zakladatel\u016f klubu.\u201c"],t.s)
B.blU=new A.a6(B.cH,B.ad3,!1)
B.amP=s(["\u201eCo kdybychom se za\u0161li pod\xedvat, odkud k n\xe1m zakladatel\xe9 p\u0159i\u0161li?\u201c"],t.s)
B.bns=new A.a6(B.bW,B.amP,!1)
B.axM=new A.aQ("\u010cerven\xe1 \u010d\xe1ra na map\u011b vede hluboko do lesa. Stoj\xedte p\u0159ed cestou z kamen\u016f, kterou blokuje trn\xed.")
B.aq2=s(["\u201eCesta z mapy vede p\u0159\xedmo tudy.\u201c"],t.s)
B.bnu=new A.a6(B.cS,B.aq2,!1)
B.aqn=s(["\u201eJ\xe1 p\u0159es ty kameny a trn\xed nejdu, Terko.\u201c"],t.s)
B.bnz=new A.a6(B.bW,B.aqn,!1)
B.al0=s(["\u201eNikdo ne\u0159ekl, \u017ee to bude snadn\xe9, K\xe1jo. Tak poj\u010f.\u201c","\u201eZa mnou! Str\xe1\u017eci se n\u011bjak\xe9ho trn\xed neboj\xed.\u201c"],t.s)
B.bl7=new A.a6(B.cH,B.al0,!1)
B.adv=s(["\u201eStr\xe1\u017eci se neboj\xed, ale bod\xe1 to \xfapln\u011b stejn\u011b jako do kohokoli jin\xe9ho.\u201c"],t.s)
B.blL=new A.a6(B.bW,B.adv,!1)
B.adD=s([B.blU,B.bns,B.axM,B.bnu,B.bnz,B.bl7,B.blL],t.a)
B.boG=new A.cq("story_03_founders_trail",B.adD)
B.axm=new A.aQ("Trn\xed se rozestoup\xed a dovol\xed v\xe1m proj\xedt d\xe1l. Na m\xfdtin\u011b s m\u011bkk\xfdm bahnem jsou jemn\xe9 otisky kv\u011btin.")
B.ag_=s(["\u201eKdo by v\xe1lel kv\u011btiny v bahn\u011b?\u201c"],t.s)
B.bnM=new A.a6(B.bW,B.ag_,!1)
B.am9=s(["\u201eZakladatel\xe9 klubu takto zna\u010dili cestu.\u201c","\u201eAle ne! Vypad\xe1 to, \u017ee je n\u011bkdo odnesl.\u201c"],t.s)
B.bmW=new A.a6(B.cS,B.am9,!1)
B.apH=s(["\u201eA co s t\xedm te\u010f budeme d\u011blat? J\xe1 u\u017e m\xe1m bahno po kotn\xedky!\u201c"],t.s)
B.bn7=new A.a6(B.bW,B.apH,!1)
B.ahI=s(["\u201ePod\xedv\xe1me se kolem, jestli n\u011bjak\xe9 nenajdeme.\u201c"],t.s)
B.bmN=new A.a6(B.cH,B.ahI,!1)
B.acx=s([B.axm,B.bnM,B.bmW,B.bn7,B.bmN],t.a)
B.boA=new A.cq("story_04_flowers_in_mud",B.acx)
B.axR=new A.aQ("Posledn\xed kv\u011btina zapadne na sv\xe9 m\xedsto a cel\xe1 m\xfdtina rozkvete. Mezi kv\u011bty se objev\xed \xfazk\xe1 p\u011b\u0161inka, kter\xe1 kon\u010d\xed u mohutn\xe9ho dubu.")
B.aeU=s(["\u201eTen dub je ur\u010dit\u011b star\u0161\xed ne\u017e my v\u0161ichni dohromady.\u201c"],t.s)
B.bli=new A.a6(B.bW,B.aeU,!1)
B.abS=s(["\u201ePodle kmene m\xe1 aspo\u0148 p\u011bt set let.\u201c","\u201eHele veverka a vypad\xe1, \u017ee n\u011bco hl\xedd\xe1.\u201c"],t.s)
B.bmD=new A.a6(B.cS,B.abS,!1)
B.aik=s(["\u201eKouk\xe1 na m\u011b n\u011bjak hladov\u011b.\u201c"],t.s)
B.bnX=new A.a6(B.bW,B.aik,!1)
B.arW=s(["\u201ePoj\u010fme se pod\xedvat bl\xed\u017e.\u201c"],t.s)
B.blK=new A.a6(B.cH,B.arW,!1)
B.alx=s([B.axR,B.bli,B.bmD,B.bnX,B.blK],t.a)
B.bpm=new A.cq("story_05_old_oak",B.alx)
B.axN=new A.aQ("\u017daludy zmiz\xed v dutin\u011b dubu. Star\xfd dub se rozz\xe1\u0159\xed tepl\xfdm sv\u011btlem a zlat\xe1 z\xe1\u0159e miz\xed v d\xe1lce.")
B.amU=s(["\u201eCo se to stalo?\u201c"],t.s)
B.bnA=new A.a6(B.bW,B.amU,!1)
B.ai7=s(["\u201eVypad\xe1 to, jako bychom n\u011bco probudili.\u201c"],t.s)
B.blI=new A.a6(B.cH,B.ai7,!1)
B.af2=s(["\u201ePros\xedm, a\u0165 je to n\u011bco roztomil\xe9ho.\u201c"],t.s)
B.blG=new A.a6(B.bW,B.af2,!1)
B.aj1=s(["\u201eZa sv\u011btlem! Dub n\xe1m ukazuje cestu.\u201c"],t.s)
B.bmQ=new A.a6(B.cH,B.aj1,!1)
B.axt=new A.aQ("Jdete sm\u011brem k z\xe1\u0159i. Zlat\xe9 sv\u011btlo v\xe1s dovede a\u017e k vodop\xe1du, kde ve skaln\xedm v\xfdklenku le\u017e\xed star\xe1 truhla.")
B.aio=s(["\u201eTakovou truhlu jsem je\u0161t\u011b nevid\u011bla.\u201c"],t.s)
B.bmx=new A.a6(B.cS,B.aio,!1)
B.arA=s([B.axN,B.bnA,B.blI,B.blG,B.bmQ,B.axt,B.bmx],t.a)
B.boH=new A.cq("story_06_waterfall_chest",B.arA)
B.ay5=new A.aQ("V\xedko se zvedne. Uvnit\u0159 le\u017e\xed svitek p\u0159ev\xe1zan\xfd prov\xe1zkem.")
B.agv=s(["\u201eSlunce u\u017e se dot\xfdk\xe1 korun strom\u016f!\u201c"],t.s)
B.bnZ=new A.a6(B.cS,B.agv,!1)
B.art=s(["\u201eHonem zp\u011bt do klubovny!\u201c","\u201eNev\xedme, co ten svitek skr\xfdv\xe1. Mus\xedme b\xfdt opatrn\xed.\u201c"],t.s)
B.blJ=new A.a6(B.cH,B.art,!1)
B.ayz=new A.aQ("Po n\xe1vratu do klubovny otev\u0159e\u0161 svitek. Sotva ho rozvine\u0161, vyl\xe9tnou z n\u011bj velk\xe9 bubliny.")
B.arI=s([B.ay5,B.bnZ,B.blJ,B.ayz],t.a)
B.bp2=new A.cq("story_07_scroll",B.arI)
B.ax7=new A.aQ("Posledn\xed paprsek slunce dopadne na svitek a klubovna se rozsv\xedt\xed lucernami.")
B.apx=s(["\u201eTo je v\u0161echno? J\xe1 \u010dekal poklad.\u201c"],t.s)
B.bnN=new A.a6(B.bW,B.apx,!1)
B.anE=s(["\u201eCel\xe1 ta cesta byla zkou\u0161ka, K\xe1jo. Cht\u011bli zjistit, jestli m\xe1me trp\u011blivost.\u201c"],t.s)
B.bks=new A.a6(B.cS,B.anE,!1)
B.afe=s(["\u201eA pro\u010d to nenapsali rovnou na dve\u0159e?\u201c"],t.s)
B.bkA=new A.a6(B.bW,B.afe,!1)
B.ajH=s(["\u201eProto\u017ee by t\u011b nebavilo to hledat.\u201c"],t.s)
B.blj=new A.a6(B.cS,B.ajH,!1)
B.akJ=s(["\u201eTrp\u011blivost \u2026 ta mi nikdy moc ne\u0161la.\u201c"],t.s)
B.bnw=new A.a6(B.cH,B.akJ,!1)
B.aly=s(["\u201eMarku, ty jsi v \u017eivot\u011b nepo\u010dkal ani na konec v\u011bty.\u201c"],t.s)
B.bkn=new A.a6(B.cS,B.aly,!1)
B.alt=s(["\u201eJ\xe1 \u010dek\xe1m na dort a trp\u011blivost m\xe1m.\u201c"],t.s)
B.bll=new A.a6(B.bW,B.alt,!1)
B.aim=s(["\u201eTo nen\xed trp\u011blivost, K\xe1jo. To je hlad.\u201c"],t.s)
B.bmf=new A.a6(B.cS,B.aim,!1)
B.aen=s(["\u201eA tob\u011b se zkou\u0161ka povedla. Bez tebe bychom to do z\xe1padu nestihli.\u201c"],t.s)
B.bl4=new A.a6(B.cH,B.aen,!1)
B.adT=s([B.ax7,B.bnN,B.bks,B.bkA,B.blj,B.bnw,B.bkn,B.bll,B.bmf,B.bl4],t.a)
